def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    threshold = 2000000
    qualifying_years = [value for value in (v1, v2) if value > threshold]
    result = len(qualifying_years)
    return {
        "value": result,
        "trace": {
            "threshold": threshold,
            "values": [v1, v2],
            "qualifying_values": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
